let db=null,transactions=[],settings=loadSettings(),activePage='overview',page=0,visibleRows=[],periodSelection=null,editingRuleId=null;
let comparisonSort={key:'current',direction:'desc'},merchantSort={key:'spent',direction:'desc'},transactionSort={key:'date',direction:'desc'};
const $=id=>document.getElementById(id);
