const parseNum=v=>{let s=String(v??'').trim();if(!s)return 0;const negative=/^\(.*\)$/.test(s)||s.includes('-');s=s.replace(/[()\s\u00a0]/g,'').replace(/[^0-9.,]/g,'');if(!/\d/.test(s))return 0;const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');let decimal='';if(comma>=0&&dot>=0)decimal=comma>dot?',':'.';else if(comma>=0||dot>=0){const sep=comma>=0?',':'.',parts=s.split(sep),tail=parts[parts.length-1];if(parts.length===2&&tail.length>0&&tail.length<=2)decimal=sep;else if(parts.length>2&&tail.length>0&&tail.length<=2)decimal=sep;}let normalized=s;if(decimal){const other=decimal===','?'.':',';normalized=normalized.split(other).join('');const at=normalized.lastIndexOf(decimal);normalized=normalized.slice(0,at).split(decimal).join('')+'.'+normalized.slice(at+1);}else normalized=normalized.replace(/[.,]/g,'');const n=Number(normalized);return Number.isFinite(n)?(negative?-Math.abs(n):n):0;};
const parseBalanceValue=v=>{const s=String(v??'').trim();return s&&/\d/.test(s)?parseNum(s):null;};
const todayISO=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
function loadSettings(){try{const old=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}');return Object.assign({},DEFAULT_SETTINGS,old,{merchantCategories:Object.assign({},DEFAULT_SETTINGS.merchantCategories,old.merchantCategories||{}),incidental:Object.assign({},DEFAULT_SETTINGS.incidental,old.incidental||{}),forecast:Object.assign({},DEFAULT_SETTINGS.forecast,old.forecast||{})});}catch(e){return JSON.parse(JSON.stringify(DEFAULT_SETTINGS));}}
function saveSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbAll(){return new Promise((resolve,reject)=>{const req=db.transaction(STORE,'readonly').objectStore(STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);});}
function dbPutMany(items){return new Promise((resolve,reject)=>{if(!items.length)return resolve();const tx=db.transaction(STORE,'readwrite'),store=tx.objectStore(STORE);items.forEach(x=>store.put(x));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
