function renderAll(){renderStatus();renderOverview();renderCompare();renderProjects();renderRules();renderMerchants();renderTransactions();renderForecast();}
function setPage(name){activePage=name;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+name));document.querySelectorAll('.home-section').forEach(el=>el.classList.toggle('home-section-hidden',name!=='overview'));}
