function showMessage(msg,isError){$('importMessage').textContent=msg;$('importMessage').style.color=isError?'#b44a4a':'';}
async function importFiles(){const tasks=[{account:'Dan',input:$('danFiles')},{account:'Anca',input:$('ancaFiles')}];const selected=tasks.flatMap(x=>[...x.input.files].map(file=>({account:x.account,file})));if(!selected.length){showMessage('Choose at least one CSV file for Dan or Anca.',true);return;}$('importBtn').disabled=true;showMessage('Reading and validating CSV files…');try{const seen=new Set(transactions.map(t=>t.id));const add=[];let parsed=0,duplicates=0;for(const item of selected){const content=await item.file.text();const rows=parseStatement(content,item.account,item.file.name);parsed+=rows.length;for(const t of rows){if(seen.has(t.id)){duplicates++;continue;}seen.add(t.id);add.push(t);}}await dbPutMany(add);transactions=transactions.concat(add);transactions.sort((a,b)=>a.date.localeCompare(b.date));setPeriodDefault();renderAll();showMessage('Imported '+add.length+' new transactions from '+selected.length+' file(s); skipped '+duplicates+' exact duplicate(s).');$('danFiles').value='';$('ancaFiles').value='';$('danFileNames').textContent='No files selected';$('ancaFileNames').textContent='No files selected';}catch(e){showMessage(e.message||String(e),true);}finally{$('importBtn').disabled=false;}}
function openEdit(id){const tx=transactions.find(t=>t.id===id);if(!tx)return;const c=classify(tx);$('editId').value=id;$('editTransactionLabel').textContent=tx.date+' · '+tx.account+' · '+tx.description+' · '+money(cashEffect(tx));$('editCategory').innerHTML='<option value="auto">Use automatic category ('+escapeHTML(baseClass(tx).category)+')</option>'+CATEGORIES.map(x=>'<option value="'+escapeHTML(x)+'">'+escapeHTML(x)+'</option>').join('');$('editCategory').value=tx.override?.category||'auto';$('editProject').value=tx.override?.project||'';$('editTreatment').value=tx.override?.treatment||'auto';$('editNature').value=tx.override?.nature||'auto';$('editDialog').showModal();}
